module Moderate
  class BaseController < ApplicationController
    before_action :authenticate_moderator!

    private

    def authenticate_moderator!
      authenticate_or_request_with_http_basic("Quizzy Moderator") do |username, password|
        expected_user = ENV["QUIZZY_MODERATOR_USERNAME"].to_s
        expected_pass = ENV["QUIZZY_MODERATOR_PASSWORD"].to_s
        expected_user.present? && expected_pass.present? &&
          ActiveSupport::SecurityUtils.secure_compare(username.to_s, expected_user) &&
          ActiveSupport::SecurityUtils.secure_compare(password.to_s, expected_pass)
      end
    end
  end
end

